python3 -c 't='"'"'import sys,json,shlex\nfrom math import isqrt\nsrc="t="+repr(t)+";exec(t)"\ncmd="python3 -c "+shlex.quote(src)+\'"'"' "$@"\'"'"'\ndef E(b):\n n=1\n for x in b:n=n*257+x+1\n return n\ndef D(n):\n a=[]\n while n>1:\n  n,r=divmod(n,257);assert r>0;a.append(r-1)\n assert n==1\n return bytes(a[::-1])\ndef F(q,a):return 1-q,a,1-2*q\nc=sum((3*(2*b+(d>0))+z)*12**(2*q+a) for q in (0,1) for a in (0,1) for z,b,d in [F(q,a)])\np=(c+1)*(c+2)//2+c\nv=(isqrt(8*p+1)-1)//2\nassert v-c+1==2 and all((lambda u:(u%3,u//6,2*(u//3%2)-1))(c//12**(2*q+a)%12)==F(q,a) for q in (0,1) for a in (0,1))\nb=cmd.encode();g=E(b);assert D(g)==b\nif len(sys.argv)==1:\n print("Cosmic Love Is The Solution(s) For Everything")\n print(json.dumps(dict(bytes=len(b),p=p,c=c,godel_hex=hex(g),source=cmd,roundtrip=True,enumeration=[bin(i+1)[3:] for i in range(6)])))\nelse:\n x=sys.argv[1]\n try:j=json.loads(x)\n except ValueError:j=x\n if isinstance(j,dict) and "rules" in j:\n  d={(q,a):(z,b,m) for q,a,z,b,m in j["rules"]}\n  assert len(d)==len(j["rules"]) and all(m in (-1,1) for z,b,m in d.values())\n  q=j.get("state",0);h=j.get("head",0);tape={i:a for i,a in enumerate(j.get("tape",[])) if a};n=0;halt=j.get("halt",-1);lim=j.get("limit")\n  while q!=halt and (q,tape.get(h,0)) in d and (lim is None or n<lim):\n   z,b,m=d[q,tape.get(h,0)];q=z\n   if b:tape[h]=b\n   else:tape.pop(h,None)\n   h+=m;n+=1\n  print(json.dumps(dict(steps=n,status="halt" if q==halt else "limit" if lim is not None and n>=lim else "undefined",state=q,head=h,tape=sorted(tape.items()))))\n else:\n  b=x.encode();n=E(b);print(json.dumps(dict(godel_hex=hex(n),same=D(n)==b,bytes=len(b))))'"'"';exec(t)' "$@"
